{"command": "cd /workspace && python -c "
from boltons.listutils import BarrelList

# single list boundary
bl = BarrelList([1,2,3])
try:
    print('bl[3]=', bl[3])
except IndexError:
    print('bl[3] IndexError (correct)')

# multi-sublist
bl = BarrelList(range(100000))
print('num lists', len(bl.lists))
print('len', len(bl))
try:
    print('bl[len]=', bl[len(bl)])
except IndexError:
    print('bl[len] IndexError (correct)')
for idx in [0, -1, len(bl)-1, -len(bl)]:
    print(idx, bl[idx], 'expected', list(range(100000))[idx])
"
"}

